from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            bh,bw=r1-r0+1,c1-c0+1
            if bh>=2 and bw>=2 and len(comp)/(bh*bw)>=0.70:
                objects.append((color,r0,r1,c0,c1,len(comp),bh*bw))
    out=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1,n,area in objects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
